1061	/**
1062	 * The one way an observed URL is written into the evidence.
1063	 *
1064	 * For the bounded loopback origin this is the origin-relative form it has
1065	 * always been: the port is ephemeral, so the origin is the one part that cannot
1066	 * be pinned, and everything after it is exactly what the browser requested —
1067	 * query included, because the harness's own origin mints no identifiers and its
1068	 * queries are part of what a production-static claim is about.
1069	 *
1070	 * For anything outside that origin the query is dropped, and the record is
1071	 * scheme, host and pathname. The endpoints applications of this era reach for
1072	 * carry their account identifier in the query — a measurement id, a DSN public
1073	 * key — and a published receipt has no business carrying one. What identifies
1074	 * the seam is the endpoint, and the endpoint survives intact.
1075	 */
1076	export const witnessRecordedRequestPath = (url: string, origin: string): string => {
1077		if (origin.length > 0 && url.startsWith(origin)) return url.slice(origin.length);
1078		if (isWitnessLoopbackUrl(url)) return url;
1079		const parsed = parseURL(url);
