1096		for (const request of page.failedRequests) {
1097			const entry = {
1098				method: request.method,
1099				path: witnessRecordedRequestPath(request.url, origin),
1100				reason: request.reason,
1101				count: 1,
1102			};
1103			// Admitted cancelled duplicates are accounted for instance by instance in
1104			// their own inventory, so they are not counted twice here. Everything
1105			// else — including a cancelled fetch the corroboration rule refused —
1106			// stays in this exact inventory and fails the run if it is not pinned.
1107			if (admitted.has(failedRequestKey(entry))) continue;
1108			const existing = counts.get(failedRequestKey(entry));
1109			if (existing === undefined) counts.set(failedRequestKey(entry), entry);
1110			else existing.count += 1;
1111		}
1112		return [...counts.values()].sort((left, right) =>
1113			compareUtf16CodeUnits(failedRequestKey(left), failedRequestKey(right)),
