			);
			await clean(
				context,
				page,
				JIRA_CLONE_JOURNEY_NAVIGATIONS,
				lifecycle.expectedConsoleErrors,
				// Still exact. The pinned inventory total is zero, and the second
				// term is the number of cancelled duplicate fetches this run's
